export type TransferStatus = "pending" | "accepted" | "rejected";
export type ViolationHistoryAction = "move" | "reset";

export type TransferRequest = {
  id: string;
  studentId: string;
  sourceSchoolId: string;
  destinationSchoolId: string;
  academicYearId: string;
  sourceEnrollmentId: string;
  status: TransferStatus;
  requestedBy: string;
  requestedAt: string;
  reviewedBy?: string;
  reviewedAt?: string;
  violationHistoryAction: ViolationHistoryAction;
};

const TRANSFER_REQUESTS_STORAGE_KEY = "alghassania_transfer_requests";

function readTransferRequestsFromStorage(): TransferRequest[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(TRANSFER_REQUESTS_STORAGE_KEY);
    return raw ? (JSON.parse(raw) as TransferRequest[]) : [];
  } catch {
    return [];
  }
}

function writeTransferRequestsToStorage(requests: TransferRequest[]) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(TRANSFER_REQUESTS_STORAGE_KEY, JSON.stringify(requests));
  } catch {
    // ignore storage errors
  }
}

export function getTransferRequests(): TransferRequest[] {
  return readTransferRequestsFromStorage();
}

/**
 * Get the student's active enrollment for the current academic year.
 * Returns null if not found.
 */
export function getStudentActiveEnrollment(
  studentId: string,
  academicYearId: string,
  enrollments: Enrollment[]
): Enrollment | null {
  return enrollments.find(
    (e) =>
      e.studentId === studentId &&
      e.academicYearId === academicYearId &&
      e.status === "active"
  ) ?? null;
}

/**
 * Create a new transfer request.
 * Validates:
 * - Student exists
 * - Student has an active enrollment in the current academic year
 * - The active enrollment's school matches the source school
 * - Destination school is different from source school
 * Returns the new TransferRequest or throws an error.
 * The new request is pushed to the transferRequests array.
 */
export function createTransferRequest(
  studentId: string,
  sourceSchoolId: string,
  destinationSchoolId: string,
  academicYearId: string,
  requestedBy: string,
  violationHistoryAction: ViolationHistoryAction,
  students: Student[],
  enrollments: Enrollment[]
): TransferRequest {
  // Validate student exists
  const student = students.find((s) => s.id === studentId);
  if (!student) {
    throw new Error(`Student not found: ${studentId}`);
  }

  // Get student's active enrollment for the academic year
  const sourceEnrollment = getStudentActiveEnrollment(studentId, academicYearId, enrollments);
  if (!sourceEnrollment) {
    throw new Error(`No active enrollment found for student ${studentId} in academic year ${academicYearId}`);
  }

  // Validate active enrollment belongs to source school
  if (sourceEnrollment.schoolId !== sourceSchoolId) {
    throw new Error(`Student's active enrollment is not in source school ${sourceSchoolId}`);
  }

  // Validate destination school is different
  if (destinationSchoolId === sourceSchoolId) {
    throw new Error("Destination school must be different from source school");
  }

  // Validate destination school exists
  const destSchool = schools.find((s) => s.id === destinationSchoolId);
  if (!destSchool) {
    throw new Error(`Destination school not found: ${destinationSchoolId}`);
  }

  const now = new Date().toISOString();

  const newRequest: TransferRequest = {
    id: `transfer-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    studentId,
    sourceSchoolId,
    destinationSchoolId,
    academicYearId,
    sourceEnrollmentId: sourceEnrollment.id,
    status: "pending",
    requestedBy,
    requestedAt: now,
    violationHistoryAction,
  };

  // Read existing requests from storage, add new one, write back
  const requests = readTransferRequestsFromStorage();
  requests.push(newRequest);
  writeTransferRequestsToStorage(requests);

  return newRequest;
}

/**
 * Get outgoing transfer requests for a source school.
 */
export function getOutgoingTransferRequests(schoolId: string): TransferRequest[] {
  const requests = readTransferRequestsFromStorage();
  return requests.filter((r) => r.sourceSchoolId === schoolId);
}

/**
 * Get incoming transfer requests for a destination school.
 */
export function getIncomingTransferRequests(schoolId: string): TransferRequest[] {
  const requests = readTransferRequestsFromStorage();
  return requests.filter((r) => r.destinationSchoolId === schoolId);
}

/**
 * Accept a pending transfer request.
 * Validates:
 * - Request exists and is pending
 * - Reviewer belongs to destination school
 * Updates:
 * - Source enrollment status to "transferred"
 * - Creates new enrollment for destination school
 * - Transfer request status to "accepted"
 * Returns the updated TransferRequest or throws an error.
 */
export function acceptTransferRequest(
  requestId: string,
  reviewerId: string,
  reviewerSchoolId: string,
  enrollments: Enrollment[],
  sections: Section[],
  academicYearId: string
): TransferRequest {
  const requests = readTransferRequestsFromStorage();
  const requestIndex = requests.findIndex((r) => r.id === requestId);
  if (requestIndex === -1) {
    throw new Error(`Transfer request not found: ${requestId}`);
  }

  const request = requests[requestIndex];

  if (request.status !== "pending") {
    throw new Error(`Transfer request ${requestId} is not pending (status: ${request.status})`);
  }

  if (request.destinationSchoolId !== reviewerSchoolId) {
    throw new Error(`Reviewer ${reviewerId} does not belong to destination school ${request.destinationSchoolId}`);
  }

  // Find source enrollment
  const sourceEnrollmentIndex = enrollments.findIndex((e) => e.id === request.sourceEnrollmentId);
  if (sourceEnrollmentIndex === -1) {
    throw new Error(`Source enrollment not found: ${request.sourceEnrollmentId}`);
  }

  const sourceEnrollment = enrollments[sourceEnrollmentIndex];

  // Mark source enrollment as transferred
  enrollments[sourceEnrollmentIndex] = {
    ...sourceEnrollment,
    status: "transferred",
  };

  // Find appropriate destination section for the student's class in the destination school
  const destSection = sections.find(
    (s) =>
      s.schoolId === request.destinationSchoolId &&
      s.classId === sourceEnrollment.classId &&
      s.academicYearId === academicYearId
  );

  if (!destSection) {
    throw new Error(
      `No matching section found in destination school ${request.destinationSchoolId} for class ${sourceEnrollment.classId} in academic year ${academicYearId}`
    );
  }

  // Create new enrollment for destination school
  const newEnrollment: Enrollment = {
    id: `enrollment-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    studentId: request.studentId,
    academicYearId: request.academicYearId,
    classId: sourceEnrollment.classId,
    sectionId: destSection.id,
    schoolId: request.destinationSchoolId,
    status: "active",
  };

  enrollments.push(newEnrollment);

  // Update transfer request
  const now = new Date().toISOString();
  const updatedRequest: TransferRequest = {
    ...request,
    status: "accepted",
    reviewedBy: reviewerId,
    reviewedAt: now,
  };

  requests[requestIndex] = updatedRequest;
  writeTransferRequestsToStorage(requests);

  return updatedRequest;
}

/**
 * Reject a pending transfer request.
 * Validates:
 * - Request exists and is pending
 * - Reviewer belongs to destination school
 * Updates:
 * - Transfer request status to "rejected"
 * Does NOT modify enrollments.
 * Returns the updated TransferRequest or throws an error.
 */
export function rejectTransferRequest(
  requestId: string,
  reviewerId: string,
  reviewerSchoolId: string
): TransferRequest {
  const requests = readTransferRequestsFromStorage();
  const requestIndex = requests.findIndex((r) => r.id === requestId);
  if (requestIndex === -1) {
    throw new Error(`Transfer request not found: ${requestId}`);
  }

  const request = requests[requestIndex];

  if (request.status !== "pending") {
    throw new Error(`Transfer request ${requestId} is not pending (status: ${request.status})`);
  }

  if (request.destinationSchoolId !== reviewerSchoolId) {
    throw new Error(`Reviewer ${reviewerId} does not belong to destination school ${request.destinationSchoolId}`);
  }

  const now = new Date().toISOString();
  const updatedRequest: TransferRequest = {
    ...request,
    status: "rejected",
    reviewedBy: reviewerId,
    reviewedAt: now,
  };

  requests[requestIndex] = updatedRequest;
  writeTransferRequestsToStorage(requests);

  return updatedRequest;
}


